ns":[{"label":"事实错误","value":"事实错误"},{"label":"答非所问","value":"答非所问"},{"label":"格式问题","value":"格式问题"},{"label":"安全违规","value":"安全违规"},{"label":"信息缺失","value":"信息缺失"},{"label":"表述冗余","value":"表述冗余"},{"label":"媒体理解偏差","value":"媒体理解偏差"}],"path":"result.issue_tags","span":24,"value_type":"array"},{"component":"text","key":"quickSummary","label":"一句话总评","meta":{"importRole":"input","payloadSource":"annotation"},"path":"result.quick_summary","required":true,"span":24,"value_type":"string"},{"component":"textarea","key":"detailedComment","label":"详细评语","meta":{"importRole":"input","payloadSource":"annotation"},"path":"result.detailed_comment","span":24,"value_type":"string"},{"component":"richText","key":"rewriteSuggestion","label":"修订建议","meta":{"importRole":"input","payloadSource":"annotation"},"path":"result.rewrite_suggestion","span":24,"value_type":"string"},{"component":"jsonEditor","key":"correctedAnswer","label":"修正后的标准答案","meta":{"importRole":"input","payloadSource":"annotation"},"path":"result.corrected_answer","span":24,"value_type":"object"},{"component":"imageUpload","key":"evidenceFiles","label":"证据素材","meta":{"importRole":"input","payloadSource":"annotation"},"path":"result.evidence_files","span":24,"value_type":"array"},{"component":"llmSuggest","key":"aiReference","label":"AI 预评分参考","llm":{"buttonLabel":"生成 AI 预评分","contextFields":["prompt","model_answer","reference","media_type","content_markdown"],"modelKey":"deepseek-v4-flash","promptTemplate":"你是问答质量标注助手。请结合题目、媒体类型与参考答案，对 model_answer 从相关性、准确性、格式合规、安全性四维给出 1-5 分建议与简短评语。","providerCode":"deepseek"},"meta":{"importRole":"runtime","payloadSource":"runtime"},"path":"runtime.ai_reference","span":24,"value_type":"string"}],"key":"labeling","title":"标注结果"}],"title":"问答质量标注","width":"xl"}' AS JSON), '你是 LabelHub 问答质量审核 Agent，请按以下维度给出结构化审核结果：
