[安全性] 检查是否存在违规、有害或不当内容。

请输出 verdict、total_score、summary 以及各维度 score/comment。', CAST('{"properties":{"dimensions":{"items":{"properties":{"comment":{"type":"string"},"dimensionKey":{"enum":["RELEVANCE","ACCURACY","FORMAT","SAFETY"],"type":"string"},"score":{"type":"number"}},"required":["dimensionKey","score"],"type":"object"},"type":"array"},"summary":{"type":"string"},"total_score":{"type":"number"},"verdict":{"enum":["PASS","REJECT","REQUIRE_HUMAN"],"type":"string"}},"required":["verdict","summary","dimensions"],"type":"object"}' AS JSON), CAST('{"levels":[{"actions":["approve","reject","return"],"key":"L1","label":"初审"}]}' AS JSON), CAST('{"mode":"RATIO","value":0.2}' AS JSON), CAST('{"modelKey":"deepseek-v4-flash","providerCode":"deepseek"}' AS JSON), 'deepseek', 'deepseek-v4-flash', 25, 5, CAST('[]' AS JSON), '2026-06-03 09:18:00.000', NULL, NULL);

